function validate(input) {
  const [{ Users = [], Rides = [] }] = input;
  const users = new Set(), rides = new Set();
  for (const [id, name] of Users) {
    if (id === null || name === null) return 'Every user needs an id and a name.';
    if (users.has(id)) return `User id ${id} appears twice.`;
    users.add(id);
  }
  for (const [id, user, distance] of Rides) {
    if (id === null || user === null || distance === null) return 'Every ride needs an id, a user_id and a distance.';
    if (rides.has(id)) return `Ride id ${id} appears twice.`;
    if (distance < 0) return 'distance cannot be negative.';
    rides.add(id);
  }
  return null;
}

