function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const names = small ? ['Alice', 'Bob', 'Alex', 'Lee', 'Elvis', 'Donald'] : ['Alice', 'Bob', 'Alex', 'Donald', 'Lee', 'Jonathan', 'Elvis', 'Mia', 'Noah', 'Omar', 'Priya', 'Quinn', 'Rosa', 'Sam', 'Tara', 'Uma', 'Victor', 'Wen', 'Xena', 'Yusuf', 'Zoe'];
  const distances = small ? [50, 100, 120, 150, 200] : null;
  const userCount = small ? Math.floor(rand() * 7) : 1500, rideCount = small ? Math.floor(rand() * 9) : 2000;
  const idSpace = small ? 9 : 1700;
  // Users get distinct ids drawn from a small space, so some rides point at missing users.
  const ids = [];
  for (let id = 1; id <= idSpace; id++) ids.push(id);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Users = ids.slice(0, userCount).map(id => [id, pick(names)]);
  const Rides = [];
  for (let i = 1; i <= rideCount; i++) {
    const rider = Users.length && rand() < 0.85 ? pick(Users)[0] : 1 + Math.floor(rand() * idSpace);
    Rides.push([i, rider, small ? pick(distances) : 1 + Math.floor(rand() * 500)]);
  }
  return [{ Users, Rides }];
}
